"use strict";
const $=id=>document.getElementById(id),t=OrionI18n.t;
const crates=[['☾','Moon','月亮'],['✦','Star','星星'],['❧','Leaf','葉子'],['☀','Sun','太陽']];
const journeys=[[[0,1,2],[3,1,0,2],[2,0,3,1]],[[1,2,0],[0,2,1,3],[3,1,2,0]],[[2,0,1],[1,3,2,0],[0,2,1,3]],[[0,2,1],[2,0,3,1],[1,3,0,2]],[[1,0,2],[3,2,0,1],[2,1,3,0]],[[2,1,0],[0,1,3,2],[3,0,2,1]]];
let variant=OrionProgress.variant('queue'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,pile=[],delivered=[],shipping=false,solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){return journeys[v][s].slice();}
function cargoName(id){return crates[id][0]+' '+t(crates[id][1],crates[id][2]);}
function push(id){if(solved||!Number.isInteger(id)||!challenge().includes(id)||(pile.includes(id)||delivered.includes(id)))return;pile.push(id);state='loaded';render();}
function undo(){if(solved||!pile.length)return;pile.pop();state='ready';render();}
function pop(){if(solved||!pile.length)return;shipping=true;delivered.push(pile.shift());state='unloaded';render();}
function resetTrial(){pile=[];delivered=[];shipping=false;solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('queue')){variant=v;stage=0;resetTrial();}
function check(){if(solved)return;const q=challenge();if(delivered.length!==q.length)state='incomplete';else if(delivered.some((id,i)=>id!==q[i]))state='wrong';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('boarding');}render();if(solved&&stage<2)$('next').focus();}
function hints(){return[t('Add two travellers. Which one is at the front? The last arrival joins at the back.','讓兩位旅客排隊。誰在隊首？後來的旅客加入隊尾。'),t('The earliest arrival boards first. Later arrivals wait behind them.','先到的旅客先登船，後來的在後面等候。'),t('Join the line in this order: '+challenge().map(cargoName).join(' → ')+'. Then board from the front.','依此次序排隊：'+challenge().map(cargoName).join(' → ')+'。然後從隊首登船。')];}
function render(){const q=challenge(),complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Lantern Ferry · Orion','燈火渡輪 · Orion');$('stageTitle').textContent=t(`Crossing ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 次渡河 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Ferry seals · ${p} / 3`,`渡輪封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);
$('pile').innerHTML=pile.length?pile.map((id,i)=>`<div class="crate ${i===0?'top':''}">${i+1}. ${cargoName(id)}${i===0?' <small>'+t('FRONT','隊首')+'</small>':''}</div>`).join(''):`<p>${t('Empty line','空隊列')}</p>`;$('pile').setAttribute('aria-label',t('Waiting line, front to back: ','隊列，由前至後：')+(pile.map(cargoName).join(', ')||t('empty','空')));for(let id=0;id<4;id++){$('load'+id).textContent=t('Join line: ','排隊：')+cargoName(id);$('load'+id).hidden=!q.includes(id);$('load'+id).disabled=solved||pile.includes(id)||delivered.includes(id);}$('undo').disabled=solved||!pile.length;$('pop').disabled=solved||!pile.length;
$('goal').textContent=t('Board in ticket order, first → last:','依船票次序登船，最先 → 最後：');$('target').innerHTML=q.map((id,i)=>`<li>${i+1}. ${cargoName(id)}</li>`).join('');$('received').innerHTML=delivered.length?delivered.map((id,i)=>`<li>${i+1}. ${cargoName(id)}</li>`).join(''):`<li>${t('Nobody aboard yet','尚未登船')}</li>`;$('reading').textContent=shipping?t('Boarding: the front traveller goes next. New arrivals can still join.','登船中：隊首旅客先走，新旅客仍可排隊。'):t(`Waiting: ${pile.length}. You may add a traveller or board the front traveller.`,`等候中：${pile.length} 人。你可以讓新旅客排隊，或讓隊首登船。`);
const messages={ready:['Choose a traveller to join the back of the line.','選一位旅客加入隊尾。'],loaded:['A traveller joined at the back. Who is still first?','旅客加入隊尾。現在誰仍然排第一？'],unloaded:['The front traveller boarded. Compare the boarding record.','隊首旅客登船了。比較登船紀錄。'],incomplete:['Everyone needs to join and board before you check.','讓每位旅客排隊和登船後，再檢查。'],wrong:['The ticket order is different. Retry and plan who joins first.','船票次序不同。重試並安排誰先排隊。'],success:['Everyone boarded in ticket order! A ferry seal shines.','登船次序吻合！渡輪封印亮起來了。']};$('feedback').textContent=t(...messages[state]);$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('boarding')?t('Boarding Sigil saved in your collection.','登船符印已存入收藏。'):'';}
for(let id=0;id<4;id++)$('load'+id).onclick=()=>push(id);$('undo').onclick=undo;$('pop').onclick=pop;
$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};
$('replay').onclick=()=>{const v=OrionProgress.nextVariant('queue',variant);observedVariant=OrionProgress.variant('queue');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('boarding');render();};function syncProgress(){const v=OrionProgress.variant('queue'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('boarding')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
